<template>
  <AppLayout>
    <div class="mx-auto max-w-7xl space-y-6">
      <!-- Hero: greeting + date, with search over the form cards below. -->
      <section
        class="relative overflow-hidden rounded-2xl bg-gradient-to-br from-gray-900 to-gray-700 px-5 py-6 text-white shadow-sm dark:from-gray-800 dark:to-gray-900 sm:px-8 sm:py-8"
      >
        <div class="pointer-events-none absolute -right-10 -top-10 h-40 w-40 rounded-full bg-white/5" />
        <div class="pointer-events-none absolute -bottom-16 right-24 h-48 w-48 rounded-full bg-white/5" />
        <div class="relative flex flex-col gap-5 md:flex-row md:items-end md:justify-between">
          <div class="min-w-0">
            <p class="text-xs font-medium uppercase tracking-wider text-gray-300">{{ todayLabel }}</p>
            <h1 class="mt-1 text-xl font-semibold sm:text-2xl">{{ greeting }}</h1>
            <p class="mt-1 text-sm text-gray-300">Pick a form to view records or start a new entry.</p>
          </div>
          <div class="relative w-full md:w-72">
            <LucideIcon
              name="search"
              class="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400"
            />
            <input
              v-model="search"
              type="search"
              placeholder="Find a form…"
              class="h-10 w-full rounded-lg border-0 bg-white/10 pl-9 pr-3 text-sm text-white placeholder-gray-400 ring-1 ring-white/20 focus:bg-white/15 focus:outline-none focus:ring-2 focus:ring-white/40"
            />
          </div>
        </div>
      </section>

      <!-- Today at a glance: same numbers as the Work Orders page. Hidden
      when the user has no linked Health Worker - the API returns all zeros
      with health_worker_linked=false then, which would misread as "all clear". -->
      <section v-if="showGlance" class="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <router-link
          v-for="card in glanceCards"
          :key="card.key"
          :to="{ name: 'WorkOrders' }"
          class="flex items-center gap-3 rounded-xl bg-white p-4 shadow-sm ring-1 ring-gray-200 transition hover:shadow-md hover:ring-gray-300 dark:bg-gray-900 dark:ring-gray-800 dark:hover:ring-gray-700"
        >
          <span class="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-lg" :class="card.iconClass">
            <LucideIcon :name="card.icon" class="h-5 w-5" />
          </span>
          <div class="min-w-0">
            <Skeleton v-if="glanceLoading" width="2rem" height="1.25rem" />
            <p v-else class="text-xl font-semibold leading-tight text-gray-900 dark:text-gray-100">
              {{ glance[card.key] ?? 0 }}
            </p>
            <p class="truncate text-xs text-gray-500 dark:text-gray-400">{{ card.label }}</p>
          </div>
        </router-link>
      </section>

      <!-- Forms -->
      <div v-if="modulesResource.loading && !modulesResource.data" :class="gridClass">
        <div
          v-for="i in 8"
          :key="i"
          class="flex items-center gap-4 rounded-xl bg-white p-4 ring-1 ring-gray-200 dark:bg-gray-900 dark:ring-gray-800"
        >
          <Skeleton width="2.75rem" height="2.75rem" />
          <div class="flex-1 space-y-2">
            <Skeleton width="70%" height="0.875rem" />
            <Skeleton width="40%" height="0.75rem" />
          </div>
        </div>
      </div>
      <ErrorMessage v-else-if="modulesResource.error" :message="modulesResource.error" />
      <div
        v-else-if="!modules.length"
        class="rounded-xl border border-dashed py-12 text-center text-sm text-gray-500 dark:border-gray-700 dark:text-gray-400"
      >
        No modules are configured for your account yet. Ask a coordinator to
        enable modules in App Module Setting.
      </div>
      <template v-else>
        <section v-for="mod in filteredModules" :key="mod.label">
          <h2 class="mb-3 flex items-center gap-2 text-sm font-semibold text-gray-900 dark:text-gray-100">
            <LucideIcon :name="mod.icon" class="h-4 w-4 text-gray-500" />
            {{ mod.label }}
            <span class="rounded-full bg-gray-100 px-2 py-0.5 text-xs font-medium text-gray-600 dark:bg-gray-800 dark:text-gray-400">
              {{ mod.doctypes.length }}
            </span>
          </h2>
          <div :class="gridClass">
            <!-- Card is a plain div (not a link) because it holds two
            separate actions - nesting the "+ New" link inside an outer link
            is invalid HTML. The stretched ::after on the title link makes
            the whole card clickable anyway; "+ New" sits above it (z-10). -->
            <div
              v-for="item in mod.doctypes"
              :key="item.route"
              class="group relative flex items-center gap-4 rounded-xl bg-white p-4 shadow-sm ring-1 ring-gray-200 transition hover:-translate-y-0.5 hover:shadow-md hover:ring-gray-300 focus-within:ring-2 focus-within:ring-gray-400 dark:bg-gray-900 dark:ring-gray-800 dark:hover:ring-gray-700"
            >
              <span
                class="flex h-11 w-11 flex-shrink-0 items-center justify-center rounded-xl"
                :class="item.color"
              >
                <LucideIcon :name="item.icon || mod.icon" class="h-5 w-5" />
              </span>
              <div class="min-w-0 flex-1">
                <router-link
                  :to="{ name: 'DoctypeList', params: { doctypeRoute: item.route } }"
                  :title="item.displayLabel"
                  class="line-clamp-2 text-sm font-medium leading-snug text-gray-900 after:absolute after:inset-0 after:rounded-xl focus:outline-none dark:text-gray-100"
                >
                  {{ item.displayLabel }}
                </router-link>
                <Skeleton v-if="countsLoading" width="3.5rem" height="0.75rem" class="mt-1.5" />
                <p v-else class="mt-0.5 text-xs text-gray-500 dark:text-gray-400">
                  <template v-if="countFor(item) != null">
                    {{ countFor(item) }} {{ countFor(item) === 1 ? 'record' : 'records' }}
                  </template>
                  <template v-else>View records</template>
                </p>
              </div>
              <router-link
                :to="{ name: 'DoctypeNew', params: { doctypeRoute: item.route } }"
                :title="`New ${item.displayLabel}`"
                :aria-label="`New ${item.displayLabel}`"
                class="relative z-10 flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-lg text-gray-400 transition hover:bg-gray-900 hover:text-white focus:outline-none focus-visible:ring-2 focus-visible:ring-gray-400 dark:hover:bg-gray-100 dark:hover:text-gray-900"
              >
                <LucideIcon name="plus" class="h-4 w-4" />
              </router-link>
            </div>
          </div>
        </section>

        <div
          v-if="!filteredModules.length"
          class="rounded-xl border border-dashed py-12 text-center text-sm text-gray-500 dark:border-gray-700 dark:text-gray-400"
        >
          No forms match “{{ search }}”.
        </div>
      </template>
    </div>
  </AppLayout>
</template>

<script setup>
import { computed, ref } from 'vue'
import { ErrorMessage, useCall } from 'frappe-ui'
import AppLayout from '@/layouts/AppLayout.vue'
import Skeleton from '@/components/Skeleton.vue'
import LucideIcon from '@/components/LucideIcon.vue'
import { modulesResource } from '@/data/modules'
import { setPageTitle } from '@/data/pageTitle'
import { session } from '@/data/session'

setPageTitle('Home')

const search = ref('')

const gridClass = 'grid grid-cols-1 gap-3 min-[480px]:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-4'

// Full class strings (not built from a color name) so Tailwind's content
// scan picks them up; cycled per card so neighbouring forms are easy to
// tell apart at a glance.
const TILE_COLORS = [
  'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-200',
  'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-200',
  'bg-purple-100 text-purple-700 dark:bg-purple-900 dark:text-purple-200',
  'bg-orange-100 text-orange-700 dark:bg-orange-900 dark:text-orange-200',
  'bg-teal-100 text-teal-700 dark:bg-teal-900 dark:text-teal-200',
  'bg-pink-100 text-pink-700 dark:bg-pink-900 dark:text-pink-200',
]

// Colour is assigned before search filtering so a card keeps the same
// colour while the user types, instead of shifting as others drop out.
const modules = computed(() =>
  (modulesResource.data || [])
    .filter((mod) => mod.doctypes?.length)
    .map((mod) => ({
      ...mod,
      doctypes: mod.doctypes.map((item, index) => ({
        ...item,
        displayLabel: item.label || item.doctype_name,
        color: TILE_COLORS[index % TILE_COLORS.length],
      })),
    })),
)

const filteredModules = computed(() => {
  const term = search.value.trim().toLowerCase()
  if (!term) return modules.value
  return modules.value
    .map((mod) => ({
      ...mod,
      doctypes: mod.doctypes.filter((item) => item.displayLabel.toLowerCase().includes(term)),
    }))
    .filter((mod) => mod.doctypes.length)
})

// Own instances (not the shared data/workOrders.js resource) so Home's
// unfiltered fetch never overwrites the filtered summary Work Orders holds.
const countsResource = useCall({
  url: '/api/v2/method/chw.api.get_module_record_counts',
  method: 'GET',
  cacheKey: 'chw-home-record-counts',
})
const glanceResource = useCall({
  url: '/api/v2/method/chw.api.get_chw_work_order_summary',
  method: 'GET',
  cacheKey: 'chw-home-glance',
})

const countsLoading = computed(() => countsResource.loading && !countsResource.data)

function countFor(item) {
  const value = countsResource.data?.[item.doctype_name]
  return typeof value === 'number' ? value : null
}

const glance = computed(() => glanceResource.data || {})
const glanceLoading = computed(() => glanceResource.loading && !glanceResource.data)
// A failed summary call just drops the strip rather than showing zeros.
const showGlance = computed(
  () => !glanceResource.error && (glanceLoading.value || glance.value.health_worker_linked !== false),
)

const glanceCards = [
  { key: 'today', label: 'Visits due today', icon: 'calendar-check', iconClass: 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-200' },
  { key: 'overdue', label: 'Overdue / missed', icon: 'alarm-clock', iconClass: 'bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-200' },
  { key: 'high_risk', label: 'High risk', icon: 'triangle-alert', iconClass: 'bg-pink-100 text-pink-700 dark:bg-pink-900 dark:text-pink-200' },
  { key: 'completed', label: 'Completed this week', icon: 'circle-check', iconClass: 'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-200' },
]

const todayLabel = new Date().toLocaleDateString(undefined, {
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  year: 'numeric',
})

const greeting = computed(() => {
  const hour = new Date().getHours()
  const timeGreeting = hour < 12 ? 'Good morning' : hour < 17 ? 'Good afternoon' : 'Good evening'
  const firstName = (session.full_name || '').split(' ')[0] || session.user
  return firstName ? `${timeGreeting}, ${firstName}` : timeGreeting
})
</script>
